"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Filter, Trash2, CheckCircle, MoreHorizontal, 
  MessageSquare, Star, Clock, AlertCircle, Reply
} from "lucide-react";

// DATA DUMMY ASPIRASI
const initialMessages = [
  { 
    id: 1, 
    sender: "Rian (XI RPL 1)", 
    category: "Sarana", 
    subject: "AC di Lab Komputer Panas", 
    preview: "Assalamualaikum kak, mau lapor AC di Lab 2 mati satu, jadi panas banget pas praktek...", 
    date: "10:45 AM", 
    status: "unread", // unread, read, done
    isStarred: true 
  },
  { 
    id: 2, 
    sender: "Siska (X TKJ 2)", 
    category: "Event", 
    subject: "Request Guest Star Pensi", 
    preview: "Kak, tahun ini undang Tulus dong buat pensi sekolah! Pasti tiketnya laku keras...", 
    date: "Kemarin", 
    status: "read",
    isStarred: false 
  },
  { 
    id: 3, 
    sender: "Anonim", 
    category: "Kurikulum", 
    subject: "Jadwal Pelajaran Bentrok", 
    preview: "Min, jadwal olahraga kelas kami bentrok sama jam istirahat, mohon ditinjau...", 
    date: "2 Jan", 
    status: "done",
    isStarred: false 
  },
  { 
    id: 4, 
    sender: "Budi (XII OTKP)", 
    category: "Umum", 
    subject: "Parkiran Motor Sempit", 
    preview: "Tolong dong parkiran dirapikan lagi, motor sering baret karena desak-desakan...", 
    date: "1 Jan", 
    status: "read",
    isStarred: false 
  },
];

export default function InboxPage() {
  const [messages, setMessages] = useState(initialMessages);
  const [selectedTab, setSelectedTab] = useState("all"); // all, unread, done
  const [searchQuery, setSearchQuery] = useState("");

  // Filter Logic
  const filteredMessages = messages.filter((msg) => {
    const matchesTab = 
      selectedTab === "all" ? msg.status !== "done" : 
      selectedTab === "done" ? msg.status === "done" :
      selectedTab === "unread" ? msg.status === "unread" : true;
    
    const matchesSearch = 
      msg.sender.toLowerCase().includes(searchQuery.toLowerCase()) || 
      msg.subject.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesTab && matchesSearch;
  });

  const handleMarkDone = (id: number) => {
    setMessages(messages.map(m => m.id === id ? { ...m, status: "done" } : m));
    alert("Pesan ditandai selesai! ✅");
  };

  const handleDelete = (id: number) => {
    if(confirm("Hapus pesan ini?")) {
      setMessages(messages.filter(m => m.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold font-black text-slate-900 dark:text-white tracking-tight">
            Inbox Aspirasi 📩
          </h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm">
            Dengar suara siswa, wujudkan perubahan nyata.
          </p>
        </div>
        
        {/* Search Bar */}
        <div className="relative w-full md:w-72 group">
           <input 
             type="text" 
             placeholder="Cari pesan..." 
             value={searchQuery}
             onChange={(e) => setSearchQuery(e.target.value)}
             className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm text-slate-700 dark:text-white placeholder:text-slate-400"
           />
           <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
        </div>
      </div>

      {/* MAIN LAYOUT (Tabs & List) */}
      <div className="bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-[2rem] overflow-hidden shadow-sm min-h-[600px] flex flex-col md:flex-row">
        
        {/* LEFT: Sidebar Filter (Tabs) */}
        <div className="w-full md:w-64 border-b md:border-b-0 md:border-r border-slate-200 dark:border-white/10 p-4 bg-slate-50/50 dark:bg-white/5">
           <button className="w-full py-3 mb-6 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-500/30 flex items-center justify-center gap-2 transition-all">
              <Filter size={16} /> Filter Lanjutan
           </button>

           <div className="space-y-1">
              {[
                { id: "all", label: "Kotak Masuk", icon: MessageSquare, count: messages.filter(m => m.status !== "done").length },
                { id: "unread", label: "Belum Dibaca", icon: AlertCircle, count: messages.filter(m => m.status === "unread").length },
                { id: "done", label: "Selesai / Arsip", icon: CheckCircle, count: messages.filter(m => m.status === "done").length },
              ].map((tab) => (
                <button 
                  key={tab.id}
                  onClick={() => setSelectedTab(tab.id)}
                  className={`w-full flex items-center justify-between px-4 py-3 rounded-xl text-sm font-bold transition-all
                    ${selectedTab === tab.id 
                      ? "bg-blue-100 dark:bg-blue-600/20 text-blue-600 dark:text-blue-400" 
                      : "text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-white/5"
                    }
                  `}
                >
                   <div className="flex items-center gap-3">
                      <tab.icon size={18} />
                      {tab.label}
                   </div>
                   {tab.count > 0 && (
                     <span className={`text-[10px] px-2 py-0.5 rounded-full 
                       ${selectedTab === tab.id ? "bg-blue-200 dark:bg-blue-500/30" : "bg-slate-200 dark:bg-white/10"}
                     `}>
                       {tab.count}
                     </span>
                   )}
                </button>
              ))}
           </div>
        </div>

        {/* RIGHT: Message List */}
        <div className="flex-1 p-2 md:p-4 bg-white/50 dark:bg-transparent">
           
           <div className="space-y-2">
             <AnimatePresence>
               {filteredMessages.length > 0 ? (
                 filteredMessages.map((msg) => (
                   <motion.div 
                     key={msg.id}
                     initial={{ opacity: 0, y: 10 }}
                     animate={{ opacity: 1, y: 0 }}
                     exit={{ opacity: 0, x: -10 }}
                     className={`group relative p-4 rounded-xl border transition-all cursor-pointer hover:shadow-md
                       ${msg.status === "unread" 
                         ? "bg-white dark:bg-white/5 border-blue-200 dark:border-blue-500/30" 
                         : "bg-slate-50 dark:bg-transparent border-slate-100 dark:border-white/5 opacity-80 hover:opacity-100"
                       }
                     `}
                   >
                      <div className="flex justify-between items-start mb-2">
                         <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white
                               ${msg.category === "Sarana" ? "bg-orange-500" : 
                                 msg.category === "Event" ? "bg-purple-500" : 
                                 "bg-blue-500"}
                            `}>
                               {msg.sender.charAt(0)}
                            </div>
                            <div>
                               <h4 className={`text-sm ${msg.status === "unread" ? "font-bold text-slate-900 dark:text-white" : "font-medium text-slate-600 dark:text-slate-300"}`}>
                                 {msg.sender}
                               </h4>
                               <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                 <Clock size={10} /> {msg.date} • {msg.category}
                               </span>
                            </div>
                         </div>

                         {/* Action Buttons (Muncul Pas Hover) */}
                         <div className="flex items-center gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                            <button title="Balas" className="p-2 hover:bg-blue-100 dark:hover:bg-blue-900/30 text-blue-500 rounded-lg transition-colors">
                               <Reply size={16} />
                            </button>
                            {msg.status !== "done" && (
                              <button onClick={() => handleMarkDone(msg.id)} title="Tandai Selesai" className="p-2 hover:bg-green-100 dark:hover:bg-green-900/30 text-green-500 rounded-lg transition-colors">
                                 <CheckCircle size={16} />
                              </button>
                            )}
                            <button onClick={() => handleDelete(msg.id)} title="Hapus" className="p-2 hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 rounded-lg transition-colors">
                               <Trash2 size={16} />
                            </button>
                         </div>
                      </div>

                      <h3 className={`text-sm mb-1 ${msg.status === "unread" ? "font-bold text-slate-800 dark:text-slate-100" : "font-medium text-slate-600 dark:text-slate-400"}`}>
                        {msg.subject}
                      </h3>
                      <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2">
                        {msg.preview}
                      </p>

                      {msg.isStarred && (
                        <div className="absolute top-4 right-4 text-yellow-500">
                           <Star size={14} fill="currentColor" />
                        </div>
                      )}
                   </motion.div>
                 ))
               ) : (
                 <div className="flex flex-col items-center justify-center h-96 text-center text-slate-400">
                    <div className="w-16 h-16 bg-slate-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4">
                       <MessageSquare size={24} className="opacity-50" />
                    </div>
                    <p className="text-sm font-medium">Tidak ada pesan ditemukan.</p>
                 </div>
               )}
             </AnimatePresence>
           </div>

        </div>

      </div>

    </div>
  );
}